// ===== Moje mody =====
async function modsLoad(){const gv=$('sel').value,l=await mib.call('mods:list',gv);if(window.mibProfileUI)mibProfileUI.modsShown(gv);$('mhead').textContent='MiB '+gv;$('mu').textContent='';
 $('mlist').innerHTML=l.length?l.map(m=>m.mib?`<div class="card mrow"><span>${tr('MiB Client — mod w grze')}</span><span class="mut" style="flex:none">${tr('część launchera')}</span></div>`:`<div class="card mrow" data-f="${esc(m.file)}"><span style="${m.on?'':'opacity:.5'}">${esc(m.file.replace(/\.disabled$/,''))}</span><span class="mut" style="flex:none">${(m.size/1048576).toFixed(1)} MB</span><button class="b ghost t">${tr(m.on?'Wyłącz':'Włącz')}</button><button class="b danger d">${tr('Usuń')}</button></div>`).join(''):'<div class="empty-state"><p>'+tr('Brak zainstalowanych modów dla tej wersji.')+'</p><button class="b" id="m-hub">'+tr('Przejdź do MiB Hub')+'</button></div>';
 const mh=$('m-hub');if(mh)mh.onclick=()=>document.querySelector('.nav[data-p="hub"]').click()}
$('mlist').onclick=async e=>{const r=e.target.closest('.mrow');if(!r)return;const gv=$('sel').value,file=r.dataset.f;
 if(e.target.classList.contains('t')){await mib.call('mods:toggle',{gv,file});modsLoad()}else if(e.target.classList.contains('d')&&confirm(file+'?')){await mib.call('mods:delete',{gv,file});modsLoad()}};
$('mupd').onclick=async()=>{$('mu').textContent=tr('Sprawdzanie…');const r=await mib.call('mods:updates',$('sel').value);if(!r.length){$('mu').textContent=tr('Wszystkie mody są aktualne.');return}
 $('mu').innerHTML=r.map(x=>`<div class="card mu" data-f="${esc(x.file)}" data-id="${esc(x.id)}"><span>${esc(x.file)} → ${esc(x.ver)}</span><button class="b ghost">${tr('Aktualizuj')}</button></div>`).join('')+`<button class="b" id="mall">${tr('Aktualizuj wszystkie')}</button>`};
$('mu').onclick=async e=>{if(e.target.tagName!=='BUTTON')return;const all=e.target.id==='mall',rows=all?[...$('mu').querySelectorAll('.mu')]:[e.target.closest('.mu')];
 for(const r of rows){const x=await mib.call('mods:update',{gv:$('sel').value,file:r.dataset.f,id:r.dataset.id});if(x==='ok')r.remove();else toast(x,1)}toast(tr('Zaktualizowano'));modsLoad()};
document.querySelector('.nav[data-p="mods"]').addEventListener('click',modsLoad);
$('sel').addEventListener('change',()=>{if($('p-mods').classList.contains('on'))modsLoad()});
// Mody przeciągnięte do „Moje mody” (pliki .jar); gdzie indziej upuszczony plik nie otwiera się w oknie launchera
document.addEventListener('dragover',e=>e.preventDefault());document.addEventListener('drop',e=>e.preventDefault());
const LOADER={fabric:'Fabric',forge:'Forge',neoforge:'NeoForge',quilt:'Quilt'},DROP_ERR={not_jar:'To nie jest plik moda (.jar).',not_mod:'Ten plik nie wygląda na mod do Minecrafta.',mib_file:'Tego pliku nie można dodać.',exists:'Ten mod już jest na liście.'};
const dropMsg=x=>x.code==='wrong_loader'?(x.cur?tr('Ten mod jest na')+' '+LOADER[x.loader]+', '+tr('a ta wersja gry używa')+' '+LOADER[x.cur]+'.':tr('MiB Client obsługuje mody Fabric i Forge, a ten jest na')+' '+LOADER[x.loader]+'.'):tr(DROP_ERR[x.code]||'Nie udało się dodać moda.');
{let depth=0;const pm=$('p-mods'),files=e=>e.dataTransfer&&[...e.dataTransfer.types].includes('Files');
 pm.addEventListener('dragenter',e=>{if(!files(e))return;depth++;pm.classList.add('drop')});
 pm.addEventListener('dragleave',()=>{if(--depth<=0){depth=0;pm.classList.remove('drop')}});
 pm.addEventListener('drop',async e=>{e.preventDefault();depth=0;pm.classList.remove('drop');const paths=[...e.dataTransfer.files].map(f=>mib.filePath(f)).filter(Boolean);if(!paths.length)return;
  const r=await mib.call('mods:add',{gv:$('sel').value,paths});if(r.added.length)toast(tr('Dodano')+': '+r.added.join(', '));for(const x of r.errors)toast(x.file+': '+dropMsg(x),1);modsLoad()})}
// ===== Panel aktualności: najnowsza wersja, popularne mody, wskazówka =====
(async()=>{try{$('n-ver').textContent=(await mib.call('versions'))[0]}catch{$('n-ver').textContent=tr('Brak sieci')}
 const t=await mib.call('trending');$('n-top').innerHTML=t.map(x=>`<div class="tm hc" data-slug="${esc(x.slug)}" data-title="${esc(x.title)}"><img src="${esc(x.icon)}" onerror="this.style.visibility='hidden'"><span>${esc(x.title)}</span><em>${fmt(x.dl)}</em></div>`).join('')||'<p class="empty">'+tr('Nie udało się wczytać listy. Sprawdź połączenie z internetem.')+'</p>'})();
applyBg();setLang(LANG);

// ===== Konta Microsoft: dodawanie, przełączanie, usuwanie =====
async function accMenu(){const l=await mib.call('accounts:list');
 $('accmenu').innerHTML=l.map(a=>`<div class="ai" data-id="${esc(a.id)}"><img src="https://mc-heads.net/avatar/${encodeURIComponent(a.name)}/48" onerror="this.onerror=null;this.src=FACE" alt=""><b>${esc(a.name)}</b>${a.active?'<em>'+tr('Aktywne')+'</em>':''}<button class="rm" title="${tr('Usuń konto')}">✕</button></div>`).join('')+`<div class="ai add"><b>+ ${tr('Dodaj konto')}</b></div>`;$('accmenu').classList.add('on')}
$('accname').onclick=e=>{e.stopPropagation();$('accmenu').classList.contains('on')?$('accmenu').classList.remove('on'):accMenu()};
document.addEventListener('click',e=>{if(!e.target.closest('#accmenu')&&!e.target.closest('#accname'))$('accmenu').classList.remove('on')});
$('accmenu').onclick=async e=>{const r=e.target.closest('.ai');if(!r)return;$('accmenu').classList.remove('on');
 if(r.classList.contains('add')){try{setAcc(await mib.call('login'));toast(tr('Konto dodane'))}catch(x){log('Logowanie nieudane: '+x.message)}return}
 if(e.target.classList.contains('rm')){if(!confirm(tr('Usunąć to konto z launchera?')))return;const x=await mib.call('accounts:remove',r.dataset.id);
  if(r.querySelector('em')){logged=false;$('accn').textContent=tr('Zaloguj się');$('nick').textContent=tr('Gracz')}
  // usunięcie aktywnego konta = wylogowanie z launchera, więc także z profilu MiB
  if(x&&x.mibLoggedOut&&window.mibProfileUI){const was=mibProfileUI.loggedIn;await mibProfileUI.refresh();if(was)toast(tr('Wylogowano z launchera i z profilu MiB.'))}return}
 const x=await mib.call('accounts:switch',r.dataset.id);if(x.error)toast(x.error,1);else{setAcc(x);toast(tr('Przełączono na')+' '+x.name)}};
mib.on('account:changed',setAcc);
mib.on('relaunch',()=>{const g=$('go');g.disabled=true;g.firstChild.textContent='URUCHAMIANIE…';$('cancel').style.display='inline-block';con.style.display='block';log('Zmiana konta — uruchamianie gry ponownie…')});
mib.on('started',()=>{setProg(0);$('go').firstChild.textContent='GRA DZIAŁA'});

// ===== Latające cząsteczki w tle: pikselowe odłamki ametystu; w motywach świątecznych kolory, kierunek, większe obrazki
// (nietoperze, płatki śniegu, serca, balony…) i fajerwerki z MibThemes.fx() w themes.js =====
(()=>{const c=$('fx'),x=c.getContext('2d');let W=0,H=0,P=[],F=[],BR=[],cfg={colors:['#a855f7'],dir:-1},last=0,raf=0,nextBurst=0;
 const rnd=(a,b)=>a+Math.random()*(b-a),pick=a=>a[Math.random()*a.length|0];
 const on=()=>localStorage.getItem('mibfx')!=='0'&&!document.documentElement.classList.contains('noanim')&&!document.hidden;
 const spawn=(y)=>({x:Math.random()*W,y:y??(cfg.dir>0?-10:H+10),s:[2,3,3,4,5][Math.random()*5|0],v:8+Math.random()*18,w:Math.random()*6.3,a:.3+Math.random()*.5,c:pick(cfg.colors)});
 // side: przelatują w poprzek, fall: spadają, rise: lecą w górę; fresh = tuż poza ekranem, gotowe do wlotu
 const dims=f=>[f.t.frames[0][0].length*f.s,f.t.frames[0].length*f.s];
 function fly(t,fresh){const f={t,s:Math.round(rnd(t.size[0],t.size[1])),pal:pick(t.pals),v:rnd(t.speed[0],t.speed[1]),w:Math.random()*6.3},[w,h]=dims(f),far=Math.random()*(fresh?.4:1);
  if(t.kind==='side'){f.d=Math.random()<.5?1:-1;f.x=f.d>0?-w-far*W:W+far*W;f.y=30+Math.random()*H*.55}
  else{f.x=Math.random()*Math.max(1,W-w);f.y=!fresh?Math.random()*H:t.kind==='fall'?-h-far*H*.5:H+far*H*.5}
  return f}
 function move(f,dt){const [w,h]=dims(f);f.w+=dt;
  if(f.t.kind==='side'){f.x+=f.d*f.v*dt;if(f.d>0?f.x>W+w:f.x<-w)Object.assign(f,fly(f.t,true))}
  else if(f.t.kind==='fall'){f.y+=f.v*dt;if(f.y>H+10)Object.assign(f,fly(f.t,true))}
  else{f.y-=f.v*dt;if(f.y<-h-10)Object.assign(f,fly(f.t,true))}}
 function draw(f){const side=f.t.kind==='side',fr=f.t.frames[Math.floor(f.w*(side?7:2))%f.t.frames.length],X=Math.round(f.x+(side?0:Math.sin(f.w)*10)),Y=Math.round(f.y+(side?Math.sin(f.w*2)*10:0));
  x.globalAlpha=f.t.alpha;fr.forEach((row,j)=>[...row].forEach((ch,i)=>{const col=f.pal[ch];if(col){x.fillStyle=col;x.fillRect(X+i*f.s,Y+j*f.s,f.s,f.s)}}));x.globalAlpha=1}
 // fajerwerki (Sylwester): wybuch 18 iskier, które opadają i gasną w 1,4 s
 function burst(){const cx=rnd(W*.1,W*.9),cy=rnd(H*.12,H*.5),col=pick(cfg.bursts);
  for(let i=0;i<18;i++){const a=i/18*6.283+Math.random()*.2,v=rnd(40,90);BR.push({x:cx,y:cy,vx:Math.cos(a)*v,vy:Math.sin(a)*v,l:0,c:Math.random()<.3?'#ffffff':col,s:Math.random()<.5?2:3})}}
 function size(){const r=devicePixelRatio||1;cfg=window.MibThemes?MibThemes.fx():cfg;W=c.clientWidth;H=c.clientHeight;c.width=W*r;c.height=H*r;x.setTransform(r,0,0,r,0,0);x.imageSmoothingEnabled=false;
  P=Array.from({length:Math.round(W*H/13000)},()=>spawn(Math.random()*H));F=(cfg.flyers||[]).flatMap(t=>Array.from({length:t.n},()=>fly(t,false)));BR=[];nextBurst=1}
 function frame(t){raf=0;if(!on()){x.clearRect(0,0,W,H);return}
  const dt=Math.min(.1,(t-(last||t))/1000);last=t;
  if(dt>0||!P.length){x.clearRect(0,0,W,H);for(const p of P){p.y+=cfg.dir*p.v*dt;p.w+=dt;const sx=Math.round(p.x+Math.sin(p.w)*6),sy=Math.round(p.y);
   x.globalAlpha=p.a*(.6+.4*Math.sin(p.w*2));x.fillStyle=p.c;x.fillRect(sx,sy,p.s,p.s);if(cfg.dir>0?p.y>H+10:p.y<-10)Object.assign(p,spawn())}x.globalAlpha=1;
   for(const f of F){move(f,dt);draw(f)}
   if(cfg.bursts){nextBurst-=dt;if(nextBurst<=0){burst();nextBurst=rnd(1.2,2.6)}
    BR=BR.filter(b=>(b.l+=dt)<1.4);for(const b of BR){b.vy+=30*dt;b.x+=b.vx*dt;b.y+=b.vy*dt;x.globalAlpha=1-b.l/1.4;x.fillStyle=b.c;x.fillRect(Math.round(b.x),Math.round(b.y),b.s,b.s)}x.globalAlpha=1}}
  raf=setTimeout(()=>requestAnimationFrame(frame),33)} // ~30 klatek na sekundę wystarczy
 const start=()=>{if(!raf&&on()){last=0;raf=1;requestAnimationFrame(frame)}};
 addEventListener('resize',()=>{size();start()});document.addEventListener('visibilitychange',start);
 $('s-fx').addEventListener('change',()=>setTimeout(start,0));$('s-anim').addEventListener('change',()=>setTimeout(start,0));
 if(window.MibThemes)MibThemes.onChange(()=>{size();start()});
 size();start()})();

// ===== Aktualności od administratora (dodaje i zmienia je w Panelu admina) =====
async function loadAnn(){const l=await mib.call('prof:announcements');if(!Array.isArray(l))return;
 const date=d=>new Date(d).toLocaleDateString(LANG==='en'?'en-GB':'pl-PL');
 const cut=t=>t.length>140?t.slice(0,140)+'…':t;
 $('ann-home').innerHTML=l.slice(0,3).map(a=>`<div class="n nw${a.pinned?' pin':''}" role="button" tabindex="0"><b>${date(a.created_at)}</b><div class="nt">${esc(a.title)}</div>${a.body?`<p>${esc(cut(a.body))}</p>`:''}</div>`).join('');
 $('ann-all').innerHTML=l.length?l.map(a=>`<div class="ann${a.pinned?' pin':''}"><b>${esc(a.title)}</b>${a.body?`<p>${esc(a.body)}</p>`:''}<small>${date(a.created_at)}</small></div>`).join(''):'<p class="empty">'+tr('Na razie nie ma aktualności.')+'</p>'}
$('ann-home').onclick=e=>{if(e.target.closest('.nw'))document.querySelector('.nav[data-p="news"]').click()};
$('ann-home').onkeydown=e=>{if(e.key==='Enter'&&e.target.closest('.nw'))document.querySelector('.nav[data-p="news"]').click()};
loadAnn();setInterval(loadAnn,10*60000);window.mibLoadAnn=loadAnn;

// ===== Awaria gry =====
const CRASH={memory:'Grze zabrakło pamięci RAM. Zwiększ RAM w Ustawieniach (np. o 1 GB) i uruchom grę ponownie.',
 java:'Ta wersja gry potrzebuje innej Javy. Wyczyść pole „Java” w Ustawieniach — launcher sam dobierze właściwą.',
 jvm:'Java nie przyjęła ustawień uruchomienia. Sprawdź RAM i argumenty JVM w Ustawieniach (wybierz profil „Domyślny”).',
 mods:'Mody się ze sobą nie zgadzają albo brakuje wymaganego moda. Wyłącz ostatnio dodane mody w „Moje mody”.',
 gpu:'Problem ze sterownikiem karty graficznej. Zaktualizuj sterowniki karty graficznej i uruchom grę ponownie.',
 unknown:'Nie udało się rozpoznać przyczyny. Kliknij „Zgłoś problem”, żeby przygotować raport dla osoby, która pomaga.'};
mib.on('crashed',d=>{$('crash-t').textContent=tr(CRASH[d.cause]||CRASH.unknown);$('crash-c').textContent=tr('Kod wyjścia gry')+': '+d.code+'.'+(d.report?' '+tr('Minecraft zapisał raport awarii.'):'');$('crash').classList.add('on')});
$('crash-x').onclick=()=>$('crash').classList.remove('on');
$('crash-rep').onclick=()=>{$('crash').classList.remove('on');$('s-rep').click()};
$('crash-send').onclick=async()=>{if(await repSend('',$('crash-send')))$('crash').classList.remove('on')};
// ===== Co nowego: raz po aktualizacji, lista zmian tej wersji =====
// (po ekranie startowym i powitaniu przy pierwszym uruchomieniu)
const wnWait=setInterval(async()=>{if(!(sp.classList.contains('out')||sp.style.display==='none')||$('welcome').classList.contains('on'))return;clearInterval(wnWait);
 const w=await mib.call('whatsnew');if(!w||!window.mibUI)return;const {h}=window.mibUI,secs=MibProfile.releaseNotes(w.notes);if(!secs.length)return;
 const close=()=>ov.remove(),ov=h('div',{class:'ov on',id:'wn'},h('div',{class:'m wn-m',role:'dialog','aria-label':tr('Co nowego')},h('small',{class:'gift-kicker'},'MiB Client '+w.version),h('h3',{},tr('Co nowego')),
  h('div',{class:'wn-list'},...secs.map(x=>h('div',{class:'wn-sec'},h('h4',{},tr(x.title)),h('ul',{},...x.items.map(i=>h('li',{},i)))))),h('div',{class:'row',style:'justify-content:flex-end'},h('button',{class:'b',id:'wn-ok',type:'button',on:{click:close}},tr('Super!')))));
 ov.addEventListener('keydown',e=>{if(e.key==='Escape')close()});document.body.append(ov);$('wn-ok').focus()},500);

